  ('ge-property-short-term', 3, '{"schemaVersion":1,"routeId":"ge-property-short-term","number":3,"corrects":2,"title":"Georgian short-term residence permit for owners of real estate worth more than USD 150,000, with their spouse and children","country":"GE","tags":["investment","temporary-residence"],"effectiveFrom":"2026-09-01","status":"open","currency":"USD","leapDayBirthday":"unsettled","sources":[{"id":"aliens-law-short-term","url":"https://matsne.gov.ge/en/document/view/2278806?publication=23","title":"Law on the Legal Status of Aliens and Stateless Persons, Article 15 – Types of residence permits, (j): a short-term permit for an owner of real estate worth over USD 150 000, spouse and child/children","kind":"official","verifiedAt":"2026-11-20"},{"id":"aliens-law-validity","url":"https://matsne.gov.ge/en/document/view/2278806?publication=23","title":"Law on the Legal Status of Aliens and Stateless Persons, Article 16 – The validity period of a residence permit, 1(f) and 3: extended one year at a time, up to 12 years; ends if the ownership ends","kind":"official","verifiedAt":"2026-11-20"},{"id":"aliens-law-alien","url":"https://matsne.gov.ge/en/document/view/2278806?publication=23","title":"Law on the Legal Status of Aliens and Stateless Persons, Article 2 – Definition of terms, (a): alien – a person who is not a citizen of Georgia","kind":"official","verifiedAt":"2026-11-20"},{"id":"aliens-law-lawful-stay","url":"https://matsne.gov.ge/en/document/view/2278806?publication=23","title":"Law on the Legal Status of Aliens and Stateless Persons, Article 14 – Body issuing Georgian residence permits and general conditions for issuing a residence permit, 1 to 1^4","kind":"official","verifiedAt":"2026-11-20"},{"id":"aliens-law-refusal","url":"https://matsne.gov.ge/en/document/view/2278806?publication=23","title":"Law on the Legal Status of Aliens and Stateless Persons, Article 18 – Grounds for denying the issuance of Georgian residence permits, 1 and 4, as amended by Law No 1803 of 25 June 2026","kind":"official","verifiedAt":"2026-11-20"},{"id":"aliens-law-language","url":"https://matsne.gov.ge/en/document/view/2278806?publication=23","title":"Law on the Legal Status of Aliens and Stateless Persons, Article 17 – Considering and making a decision on the matter of granting a Georgian residence permit, 6: documents in Georgian","kind":"official","verifiedAt":"2026-11-20"},{"id":"aliens-law-fee","url":"https://matsne.gov.ge/en/document/view/2278806?publication=23","title":"Law on the Legal Status of Aliens and Stateless Persons, Article 70 – Georgian Visa and Georgian residence permit fees and charges, 2(b): a service fee set by a Government ordinance","kind":"official","verifiedAt":"2026-11-20"},{"id":"sda-residence-permits","url":"https://sda.gov.ge/products/%e1%83%9b%e1%83%98%e1%83%92%e1%83%a0%e1%83%90%e1%83%aa%e1%83%98%e1%83%90-%e1%83%91%e1%83%98%e1%83%9c%e1%83%90%e1%83%93%e1%83%a0%e1%83%9d%e1%83%91%e1%83%98%e1%83%a1-%e1%83%9c%e1%83%94%e1%83%91%e1%83%90/","title":"Public Service Development Agency, residence permits: short-term permit decided on the 30th, 20th or 10th day for GEL 300, 450 or 600; spouse and children apply with a copy of the holder''s permit","kind":"official","verifiedAt":"2026-11-20"},{"id":"ordinance-520-family","url":"https://matsne.gov.ge/ka/document/view/6615969","title":"Government Ordinance No 389 of 27 August 2025, amending art. 3(4) of the Rules approved by Ordinance No 520 of 2014: for a short-term permit, the holder''s permit must have more than 6 months left","kind":"official","verifiedAt":"2026-11-20"}],"countries":{"id":"countries","number":1},"formerCountries":{"id":"former-countries","number":1},"officialDomains":[{"id":"ge","number":1}],"countrySets":[],"requirements":[{"id":"property-value","title":"Liquid funds of more than USD 150,000, standing in for a Georgian property, not agricultural land, whose market value exceeds the equivalent in GEL of USD 150,000","expression":{"op":"gt","left":{"op":"fact","key":"unit.liquidAssets"},"right":{"op":"money","amount":15000000,"currency":"USD"}},"sources":["aliens-law-short-term"]},{"id":"not-georgian-citizen","title":"Not a citizen of Georgia: residence permits are issued to aliens, and an alien is a person who is not a citizen of Georgia","expression":{"op":"not","operand":{"op":"intersects","list":{"op":"fact","key":"principal.citizenships"},"set":{"op":"tokens","values":["GE"]}}},"sources":["aliens-law-alien","aliens-law-lawful-stay"]}],"assessments":[{"id":"property-ownership","title":"Ownership of the property registered under Georgian law, its market value set by a certified assessor of an accredited body; the permit ends if the ownership ends","evidence":["unit.liquidAssets"],"sources":["aliens-law-short-term","aliens-law-validity"]},{"id":"lawful-stay","title":"The owner, and each family member applying, in Georgia on a lawful ground: not as an asylum seeker, on a deferred obligation to leave, on an ordinary C visa or under Article 10(3^1)","evidence":["principal.citizenships"],"sources":["aliens-law-lawful-stay","sda-residence-permits"]},{"id":"stay-grounds","title":"May be refused: the grounds on which the alien obtained the right to stay in Georgia no longer exist","evidence":["principal.visaRefusals"],"sources":["aliens-law-refusal"]},{"id":"security","title":"May be refused: sufficient grounds to assume the residence is inadvisable for state security or public safety, or an activity that threatens them","evidence":["principal.visaRefusals"],"sources":["aliens-law-refusal"]},{"id":"criminal-record","title":"May be refused: crime against peace and humanity; wanted for a crime; final conviction in Georgia, less serious unless expunged, serious or exceptionally serious even if expunged; pending prosecution","evidence":["principal.visaRefusals"],"sources":["aliens-law-refusal"]},{"id":"disease","title":"May be refused: an infectious or other disease on the Health Ministry''s list whose nature, severity or duration may threaten the population of Georgia","evidence":["principal.visaRefusals"],"sources":["aliens-law-refusal"]},{"id":"true-documents","title":"May be refused: forged or invalid documents submitted, incorrect data in the application or significant information concealed","evidence":["principal.visaRefusals"],"sources":["aliens-law-refusal"]},{"id":"no-expulsion-proceedings","title":"No permit for an alien whose expulsion from Georgia is under review or has been decided, even while the decision is under appeal","evidence":["principal.visaRefusals"],"sources":["aliens-law-refusal"]},{"id":"documents-in-georgian","title":"Application and documents in Georgian, unless the law lets the Agency accept another language, so marriage and birth certificates need a translation; a passport with Latin data needs none","evidence":["principal.citizenships"],"sources":["aliens-law-language"]},{"id":"family-after-owner","title":"The spouse and children apply for the same permit once the owner holds it, with a copy of it and proof of the relationship; the owner''s permit must have more than 6 months left","evidence":["principal.hasSpouse"],"sources":["sda-residence-permits","ordinance-520-family"]}],"dependents":[{"id":"spouse","title":"Spouse","path":["spouse"],"condition":{"op":"bool","value":true},"sources":["aliens-law-short-term","sda-residence-permits"]},{"id":"children","title":"Child or children of the owner, of any age","path":["child"],"condition":{"op":"bool","value":true},"sources":["aliens-law-short-term","sda-residence-permits"]}],"costs":[{"id":"property","title":"Real estate in Georgia, not agricultural land, worth more than USD 150,000","kind":"capital","amount":{"op":"money","amount":15000000,"currency":"USD"},"appliesTo":"principal","sources":["aliens-law-short-term"]},{"id":"service-fee","title":"Service fee for deciding the principal''s permit application on the 30th calendar day: GEL 300 (GEL 450 on the 20th day, GEL 600 on the 10th)","kind":"fee","amou